"""MetalABI.h from one kind's table (kinds/<kind>.json): the facts the frontend compiles in for that kind.

usage: gen.py <kinds/<kind>.json> <MetalABI.h>
"""

import json
import sys
from pathlib import Path

HEADER = """\
// Generated by drivers/NativeMetal/abi/gen.py from kinds/{kind}.json: {kind}'s Metal.framework, as the frontend's
// device subclass depends on it. kLimitFields is the base class's limits table (-[_MTLDevice limits], the _limits
// ivar): each integer field _MTLDevice has an accessor of, at its offset in the table.
#pragma once
#include <cstddef>
#include <cstdint>

#define SWITCH_METAL_KIND "{kind}"

inline constexpr size_t kMTLDeviceInstanceSize = {instance_size};
inline constexpr size_t kMTLDeviceLimitsBytes = {limits_bytes};

struct LimitField {{
    const char *selector;
    uint16_t offset;
}};

inline constexpr LimitField kLimitFields[] = {{
{fields}
}};
"""


def header(table: dict) -> str:
    device = table['MTLDevice']
    fields = '\n'.join(f'    {{"{name}", 0x{offset:x}}},' for name, offset in device['limits'].items())
    return HEADER.format(
        kind=table['kind'],
        instance_size=device['instance_size'],
        limits_bytes=device['limits_bytes'],
        fields=fields,
    )


def main() -> None:
    table, out = sys.argv[1:3]
    Path(out).write_text(header(json.loads(Path(table).read_text())))


if __name__ == '__main__':
    main()
